function customHandler(params) {
  var ctx = params[params.length - 1] || {};
  function parse(j){ if (j == null) return []; try { var r = JSON.parse(j); return Array.isArray(r) ? r : []; } catch(e){ return []; } }
  function inStock(v){ return !v ? false : (v.quantity == null || v.quantity > 0); }
  var variants = parse(ctx.variantsJson);
  var axes = parse(ctx.optionsJson);
  var axisKey = ctx.axisKey || "";
  var valueKey = ctx.valueKey || "";
  var axisKeys = []; for (var a=0;a<axes.length;a++){ axisKeys.push(axes[a].key); }
  function axisDefault(ax){ if (!ax || !ax.values || !ax.values.length) return null; var i; for (i=0;i<ax.values.length;i++){ if (ax.values[i] && ax.values[i].isDefault === "true") return ax.values[i].value; } for (i=0;i<ax.values.length;i++){ if (ax.values[i] && ax.values[i].isDead !== "true") return ax.values[i].value; } return ax.values[0].value; }
  function isDeadValue(ak, vk){ for (var i=0;i<axes.length;i++){ if (axes[i].key !== ak) continue; var vals = axes[i].values || []; for (var j=0;j<vals.length;j++){ if (vals[j] && vals[j].value === vk) { return vals[j].isDead === "true"; } } } return false; }
  if (axisKey && isDeadValue(axisKey, valueKey)) { axisKey = ""; valueKey = ""; }
  var prevMap = (ctx.prevMap && typeof ctx.prevMap === "object") ? ctx.prevMap : {};
  var hasPrev = false; for (var pk in prevMap){ if (Object.prototype.hasOwnProperty.call(prevMap,pk)) { hasPrev = true; break; } }
  var map = {};
  if (hasPrev) { for (var k in prevMap) { if (Object.prototype.hasOwnProperty.call(prevMap,k)) map[k]=prevMap[k]; } }
  else { for (var d=0; d<axes.length; d++){ var dv = axisDefault(axes[d]); if (dv != null) map[axes[d].key] = dv; } }
  if (axisKey) { map[axisKey] = valueKey; }
  var valueKeys = []; for (var ak in map){ if (Object.prototype.hasOwnProperty.call(map,ak)) valueKeys.push(ak + "|" + map[ak]); }
  var complete = axisKeys.length > 0; for (var i=0;i<axisKeys.length;i++){ if (map[axisKeys[i]] == null) complete=false; }
  var resolved = null;
  if (complete) { for (var v=0; v<variants.length; v++){ var vv=variants[v]; var vo=(vv && vv.options) ? vv.options : {}; var ok=true; for (var j=0;j<axisKeys.length;j++){ if (vo[axisKeys[j]] !== map[axisKeys[j]]) { ok=false; break; } } if (ok){ resolved=vv; break; } } }
  var selectedId = (resolved && inStock(resolved)) ? String(resolved.id) : "";
  var basePrice = Number(ctx.basePrice);
  var price = resolved ? (resolved.price == null ? basePrice : Number(resolved.price)) : NaN;
  var selectedPrice = isNaN(price) ? "" : String(Number(price).toFixed(2));
  return { optionsMap: map, valueKeys: valueKeys, selectedId: selectedId, selectedPrice: selectedPrice, addEnabled: selectedId ? "true" : "false" };
}

