function customHandler(params) {
  var ctx = params[params.length - 1] || {};
  var id = ctx.categoryId != null ? String(ctx.categoryId) : "";
  var tree = ctx.tree || {};
  var childrenOf = tree.childrenOf || {};
  var parentOf = tree.parentOf || {};
  var roots = tree.roots || [];
  var isKnown = parentOf[id] != null || childrenOf[id] != null || roots.indexOf(id) >= 0;
  var cur = ctx.checked;
  var arr = Array.isArray(cur)
    ? cur
    : (typeof cur === "string" && cur ? cur.split(",") : []);
  var checked = {};
  for (var i = 0; i < arr.length; i++) {
    var v = String(arr[i]).trim();
    if (v) { checked[v] = true; }
  }
  if (id && isKnown) {
    var shouldCheck = !checked[id];
    var stack = [id];
    while (stack.length) {
      var n = stack.pop();
      if (shouldCheck) { checked[n] = true; } else { delete checked[n]; }
      var kids = childrenOf[n] || [];
      for (var k = 0; k < kids.length; k++) { stack.push(kids[k]); }
    }
    var p = parentOf[id];
    var seen = {};
    while (p != null && childrenOf[p] && !seen[p]) {
      seen[p] = true;
      var sib = childrenOf[p] || [];
      var all = sib.length > 0;
      for (var b = 0; b < sib.length; b++) {
        if (!checked[sib[b]]) { all = false; break; }
      }
      if (all) { checked[p] = true; } else { delete checked[p]; }
      p = parentOf[p];
    }
  }
  var checkedArr = [];
  for (var key in checked) { if (checked[key]) { checkedArr.push(key); } }
  var minimal = [];
  for (var m = 0; m < checkedArr.length; m++) {
    var cid = checkedArr[m];
    var par = parentOf[cid];
    if (par == null || !checked[par]) { minimal.push(cid); }
  }
  var indet = {};
  var visited = {};
  for (var c = 0; c < checkedArr.length; c++) {
    var a = parentOf[checkedArr[c]];
    while (a != null && !visited[a]) {
      visited[a] = true;
      if (!checked[a]) { indet[a] = true; }
      a = parentOf[a];
    }
  }
  var indetArr = [];
  for (var kk in indet) { if (indet[kk]) { indetArr.push(kk); } }
  return { checked: checkedArr, indeterminate: indetArr, csv: minimal.join(",") };
}

function customHandler(params) {
  var ctx = params[params.length - 1] || {};
  var id = ctx.categoryId != null ? String(ctx.categoryId) : "";
  var parentOf = (ctx.tree || {}).parentOf || {};
  var path = [];
  var cur = id;
  var guard = 0;
  while (cur != null && cur !== "" && guard < 1000) {
    path.push(cur);
    cur = parentOf[cur];
    guard++;
  }
  return { path: path };
}

function customHandler(params) {
  var ctx = params[params.length - 1] || {};
  var tree = ctx.tree || {};
  var roots = tree.roots || [];
  var childrenOf = tree.childrenOf || {};
  var parentOf = tree.parentOf || {};
  var idByToken = tree.idByToken || {};
  var isKnownId = function (v) {
    return parentOf[v] != null || childrenOf[v] != null || roots.indexOf(v) >= 0;
  };
  var resolveToken = function (v) {
    if (!v) { return null; }
    if (isKnownId(v)) { return v; }
    var byToken = Object.prototype.hasOwnProperty.call(idByToken, v)
      ? idByToken[v]
      : null;
    return byToken != null ? byToken : null;
  };
  var urlIds = [];
  if (typeof window !== "undefined") {
    try {
      var raw = new URLSearchParams(window.location.search).get("categoryFilter");
      if (raw) {
        urlIds = raw.split(",").map(function (x) { return x.trim(); }).filter(Boolean);
      }
    } catch (e) {}
  }
  var seeded = {};
  for (var i = 0; i < urlIds.length; i++) {
    var uid = resolveToken(urlIds[i]);
    if (uid == null) { continue; }
    seeded[uid] = true;
    var stack = [uid];
    while (stack.length) {
      var n = stack.pop();
      var kids = childrenOf[n] || [];
      for (var k = 0; k < kids.length; k++) { seeded[kids[k]] = true; stack.push(kids[k]); }
    }
  }
  var checked = [];
  var indeterminate = [];
  var visit = function (nid) {
    var kids = childrenOf[nid] || [];
    if (kids.length === 0) {
      if (seeded[nid]) { checked.push(nid); return "full"; }
      return "none";
    }
    var full = 0;
    var any = false;
    for (var k = 0; k < kids.length; k++) {
      var st = visit(kids[k]);
      if (st === "full") { full++; }
      if (st !== "none") { any = true; }
    }
    if (seeded[nid] || full === kids.length) { checked.push(nid); return "full"; }
    if (any) { indeterminate.push(nid); return "partial"; }
    return "none";
  };
  for (var r = 0; r < roots.length; r++) { visit(roots[r]); }
  return { checked: checked, indeterminate: indeterminate };
}

