function customHandler(params) {
  var named = params[params.length - 1] || {};
  var fetchedResult = named.fetchedProduct || {};
  var settings = named.settings || {};
  var dataset = named.dataset || {};

  // Extract current quantity from trigger dataset
  var rawCurrent = dataset.currentQuantity;
  var currentQuantity = Number(rawCurrent);
  if (!isFinite(currentQuantity) || currentQuantity < 0) { currentQuantity = 0; }

  // PRIORITY 1: Try to use product data from button dataset (zero network cost)
  var product = null;
  var datasetQty = dataset.quantityAvailable || dataset.productQuantity;
  if (datasetQty && datasetQty !== "" && datasetQty !== "undefined") {
    // Convert "unlimited" string to null for unrestricted stock
    var qtyValue = datasetQty === "unlimited" ? null : Number(datasetQty);
    product = {
      quantity: qtyValue,
      id: dataset.productId,
    };
  }

  // PRIORITY 2: Fall back to fetched product data from DB
  if (!product) {
    var rows = fetchedResult && fetchedResult.rows ? fetchedResult.rows : (Array.isArray(fetchedResult) ? fetchedResult : []);
    product = rows.length > 0 ? rows[0] : null;
  }

  if (!product) {
    return { allowed: false, message: "This product is no longer available." };
  }

  // Stock and backorder settings
  var stockManagement = settings.stockManagement === true;
  var allowBackorders = settings.allowBackorders === true;

  // Validate stock (only when stock management is on and backorders disabled)
  // Note: null/undefined quantity means "unlimited stock" — skip validation
  if (stockManagement && !allowBackorders) {
    var qty = product.quantity;
    // Null/undefined = unlimited stock, always allow
    if (qty === null || qty === undefined) {
      return { allowed: true, message: "" };
    }
    var qtyNum = Number(qty);
    if (isNaN(qtyNum) || qtyNum <= 0) {
      return { allowed: false, message: "This product is currently out of stock." };
    }
    if (currentQuantity + 1 > qtyNum) {
      return { allowed: false, message: "Only " + qtyNum + " in stock. You already have the maximum in your cart." };
    }
  }

  // Validate max quantity per product cap (applies always)
  var maxQty = settings.maxQuantityPerProduct;
  if (maxQty !== null && maxQty !== undefined && Number(maxQty) > 0) {
    if (currentQuantity >= Number(maxQty)) {
      return { allowed: false, message: "You have reached the maximum quantity for this product (" + maxQty + ")." };
    }
  }

  return { allowed: true, message: "" };
}

function customHandler() {
  if (typeof window === "undefined" || !window.location) {
    return { orderNumber: "" };
  }
  var path = String(window.location.pathname || "");
  var segments = path.split("/").filter(function (s) { return s.length > 0; });
  var last = segments.length > 0 ? segments[segments.length - 1] : "";
  try { last = decodeURIComponent(last); } catch (e) { /* leave as-is */ }
  return { orderNumber: last };
}

function customHandler(params) {
  var resolved = null;
  for (var i = 0; i < params.length; i++) {
    var p = params[i];
    if (p && typeof p === "object" && typeof p.isAnonymous === "boolean" &&
        ("accountId" in p || "userId" in p || "anonymousUserId" in p)) {
      resolved = p;
      break;
    }
  }
  if (!resolved) resolved = {};
  var userId = resolved.userId != null ? String(resolved.userId) : "";
  var anonymousUserId = resolved.anonymousUserId != null ? String(resolved.anonymousUserId) : "";
  var isAnonymous = resolved.isAnonymous === true;
  var isLoggedIn = !isAnonymous && userId.length > 0;
  return { userId: userId, anonymousUserId: anonymousUserId, isLoggedIn: isLoggedIn ? "true" : "false" };
}

function customHandler(params) {
  // Percentage added on top of every stored (NET) price, baked from the
  // merchant's invoice settings and refreshed on every publish. `0` means the
  // stored price is already what the customer pays. The cart and
  // `teleport_order_items` stay NET — the tax is added only where a price is
  // displayed, so it can never be applied twice.
  var STOREFRONT_TAX_RATE = 0;
  function applyStorefrontTax(amount) {
    var base = Number(amount);
    if (!isFinite(base)) base = 0;
    if (!(STOREFRONT_TAX_RATE > 0)) return base;
    // Rounded per UNIT (not per line) so `unit price x quantity` equals the
    // line total printed beside it.
    return Math.round(base * (1 + STOREFRONT_TAX_RATE / 100) * 100) / 100;
  }
  function grossMoney(amount) {
    if (amount == null || amount === '') return '0.00';
    var n = Number(amount);
    // A cell we cannot parse is shown as-is rather than replaced by an
    // invented price — the same rule the untaxed formatters always applied.
    if (!isFinite(n)) return String(amount);
    return applyStorefrontTax(n).toFixed(2);
  }
  // The same 2-decimal formatting WITHOUT the tax, for a value that is
  // STORED rather than displayed. The pair reads as the one decision it is:
  // does this number get shown, or written down?
  function netMoney(amount) {
    if (amount == null || amount === '') return '0.00';
    var n = Number(amount);
    if (!isFinite(n)) return String(amount);
    return n.toFixed(2);
  }
  // A line total is the GROSS UNIT price times the quantity, never the net
  // line total taxed as a lump: rounding happens once, per unit, so the unit
  // price a shopper reads really does multiply into its own line total.
  //
  // With no tax to add there is nothing to re-derive, so a stored line total
  // is returned verbatim and an untaxed store renders exactly what it always
  // did — including a hand-edited line that does not equal unit x quantity.
  function grossLineMoney(unitAmount, quantity, storedTotal) {
    var unit = Number(unitAmount);
    if ((!(STOREFRONT_TAX_RATE > 0) || !isFinite(unit)) && storedTotal != null && storedTotal !== '') {
      return grossMoney(storedTotal);
    }
    var qty = Number(quantity);
    if (!isFinite(qty) || qty <= 0) qty = 1;
    return (Math.round(applyStorefrontTax(unitAmount) * qty * 100) / 100).toFixed(2);
  }
  var rows = [];
  for (var pi = 0; pi < params.length; pi++) {
    var cand = params[pi];
    if (!cand || typeof cand !== "object") continue;
    if (Array.isArray(cand) && cand.length > 0 && cand[0] && typeof cand[0] === "object" && "order_id" in cand[0]) {
      rows = cand; break;
    }
    if (Array.isArray(cand.result) && cand.result.length > 0 && cand.result[0] && typeof cand.result[0] === "object" && "order_id" in cand.result[0]) {
      rows = cand.result; break;
    }
    if (Array.isArray(cand.rows) && cand.rows.length > 0 && cand.rows[0] && typeof cand.rows[0] === "object" && "order_id" in cand.rows[0]) {
      rows = cand.rows; break;
    }
  }
  if (rows.length === 0) {
    return {
      found: false,
      orderNumber: "",
      orderStatus: "",
      paymentStatus: "",
      paymentMethod: "",
      totalAmount: "",
      deliveryFee: "0.00",
      hasDeliveryFee: "false",
      currency: "",
      currencySymbol: "",
      invoicePdfUrl: "",
      createdAt: "",
      shippingName: "",
      customerEmail: "",
      shippingAddress: "",
      hasShippingAddress: "false",
      items: []
    };
  }
  var head = rows[0];
  function formatMoney(value, fallback) {
    if (value == null || value === "") return fallback != null ? fallback : "0.00";
    var num = typeof value === "number" ? value : parseFloat(String(value));
    if (isNaN(num)) return String(value);
    return num.toFixed(2);
  }
  function formatDate(value) {
    if (!value) return "";
    try {
      var d = new Date(value);
      if (isNaN(d.getTime())) return String(value);
      var year = d.getFullYear();
      var month = String(d.getMonth() + 1).padStart(2, "0");
      var day = String(d.getDate()).padStart(2, "0");
      return year + "-" + month + "-" + day;
    } catch (e) { return String(value); }
  }
  function titleCase(value) {
    var str = String(value || "").replace(/_/g, " ").trim();
    if (!str) return "";
    return str.charAt(0).toUpperCase() + str.slice(1);
  }
  // Minimal currency-code → symbol lookup. Mirrors the orders-list
  // parser so the two surfaces render identically. Unknown codes fall
  // through to the code itself — never returns "" — so a price always
  // renders with either a real symbol or its ISO code.
  function currencyCodeToSymbol(code) {
    if (code == null) return "";
    var upper = String(code).toUpperCase();
    var SYMBOLS = {
      USD: "$", CAD: "CA$", AUD: "A$", NZD: "NZ$", SGD: "S$", HKD: "HK$",
      EUR: "\u20AC", GBP: "\u00A3", JPY: "\u00A5", CNY: "\u00A5",
      INR: "\u20B9", KRW: "\u20A9", RUB: "\u20BD", TRY: "\u20BA",
      CHF: "CHF", SEK: "kr", NOK: "kr", DKK: "kr", PLN: "z\u0142",
      CZK: "K\u010D", HUF: "Ft", BRL: "R$", MXN: "Mex$", ZAR: "R",
      AED: "AED", SAR: "SAR", THB: "\u0E3F", PHP: "\u20B1",
      IDR: "Rp", MYR: "RM", VND: "\u20AB", ILS: "\u20AA",
    };
    return SYMBOLS[upper] || upper;
  }
  var shippingLineParts = [];
  if (head.shipping_address) shippingLineParts.push(String(head.shipping_address));
  var locality = [];
  if (head.shipping_city) locality.push(String(head.shipping_city));
  if (head.shipping_state) locality.push(String(head.shipping_state));
  if (head.shipping_zip) locality.push(String(head.shipping_zip));
  if (locality.length > 0) shippingLineParts.push(locality.join(", "));
  if (head.shipping_country) shippingLineParts.push(String(head.shipping_country));
  var shippingAddress = shippingLineParts.join("\n");
  var items = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (row.item_id == null) continue;
    var itemCurrency = row.item_currency != null ? String(row.item_currency).toUpperCase() : "";
    items.push({
      id: row.item_id != null ? String(row.item_id) : "",
      order_id: row.order_id != null ? String(row.order_id) : "",
      product_id: row.item_product_id != null ? String(row.item_product_id) : "",
