function customHandler(previousContext, params) {
  const inputCtx = params[2];
  const messagesCtx = params[3];

  const chatInputValue = inputCtx && inputCtx.value != null ? String(inputCtx.value) : "";

  let chatMessages = [];
  if (messagesCtx && messagesCtx.value != null) {
    if (typeof messagesCtx.value === "string") {
      try { chatMessages = JSON.parse(messagesCtx.value); } catch(e) { chatMessages = []; }
    } else if (Array.isArray(messagesCtx.value)) {
      chatMessages = messagesCtx.value;
    }
  }

  function renderHistory(list) {
    const lines = [];
    for (let i = 0; i < list.length; i++) {
      const entry = list[i];
      if (!entry || typeof entry !== "object") { continue; }
      const body = entry.message == null ? "" : String(entry.message).trim();
      if (!body) { continue; }
      lines.push((entry.sender === "user" ? "User" : "Assistant") + ": " + body);
    }
    return lines.slice(-10).join("\n");
  }

  const pageOrigin = typeof window !== "undefined" && window.location && window.location.origin ? window.location.origin : "";

  if (!chatInputValue.trim()) {
    return { inputValue: "", updatedMessages: chatMessages, userMessageText: "", timestamp: "", historyText: renderHistory(chatMessages), pageOrigin: pageOrigin };
  }

  const now = new Date().toISOString();
  var existingConvId = params[25] && params[25].value ? String(params[25].value) : "";
  var convId = existingConvId || (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c) { var r = Math.random() * 16 | 0; return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16); }));
  const userMsg = { id: "msg_" + Date.now(), sender: "user", message: chatInputValue.trim(), status: "sent" };
  const pendingMsg = { id: "msg_" + (Date.now() + 1), sender: "ai", message: "", status: "pending" };
  const updated = chatMessages.concat([userMsg, pendingMsg]);

  return {
    inputValue: chatInputValue,
    updatedMessages: updated,
    userMessageText: chatInputValue.trim(),
    timestamp: now,
    conversationId: convId,
    historyText: renderHistory(chatMessages),
    pageOrigin: pageOrigin
  };
}

function customHandler(previousContext, params) {
  var semanticCtx = params[13];
  var lexicalCtx = params[14];
  var taxCtx = params[30];
  var taxRate = taxCtx ? Number(taxCtx.storefrontTaxRate) : NaN;
  var taxIncluded = !!(taxCtx && taxCtx.taxIncludedInPrice === true);
  function withFinalPrices(ctx) {
    if (!ctx || !Array.isArray(ctx.rows) || !isFinite(taxRate) || taxRate <= 0 || taxIncluded) {
      return ctx;
    }
    var rows = [];
    for (var t = 0; t < ctx.rows.length; t++) {
      var row = ctx.rows[t];
      var price = row ? Number(row.price) : NaN;
      if (row && isFinite(price)) {
        var clone = {};
        for (var ck in row) { clone[ck] = row[ck]; }
        clone.final_price_incl_tax = Math.round(price * (100 + taxRate)) / 100;
        rows.push(clone);
      } else {
        rows.push(row);
      }
    }
    return { executed: ctx.executed, rowCount: ctx.rowCount, rows: rows, truncated: ctx.truncated };
  }
  var searchQuestion = "";
  var searchQuestionCtx = params[10];
  if (searchQuestionCtx && typeof searchQuestionCtx.response === "string") {
    searchQuestion = searchQuestionCtx.response.replace(/\s+/g, " ").replace(/"/g, "'").trim();
    if (searchQuestion.length > 300) {
      searchQuestion = searchQuestion.slice(0, 300);
    }
  }
  var questionClause = searchQuestion
    ? " — a live database query was run to answer this exact question: \"" + searchQuestion + "\"."
    : " — a live database query was run for this question.";
  function isAggregateColumn(name) {
    return /(^|_)(count|total|sum|avg|average|mean|median|min|max|stddev|variance)(_|$)/i.test(String(name));
  }
  function readStructuredSection(ctx, label) {
    if (!ctx || ctx.executed !== true || !Array.isArray(ctx.rows) || ctx.rows.length === 0) {
      return "";
    }
    var returned = ctx.rows.length;
    var rowCap = Math.min(returned, 25);
    var aggregateOnly = true;
    var hasAggregateColumn = false;
    for (var a = 0; a < returned; a++) {
      var aggRow = ctx.rows[a];
      if (!aggRow || typeof aggRow !== "object") { aggregateOnly = false; continue; }
      var aggCols = Object.keys(aggRow);
      if (aggCols.length === 0) { aggregateOnly = false; continue; }
      for (var ac = 0; ac < aggCols.length; ac++) {
        if (isAggregateColumn(aggCols[ac])) { hasAggregateColumn = true; }
        else { aggregateOnly = false; }
      }
    }
    var hoisted = [];
    var hoistedNames = {};
    if (!aggregateOnly && hasAggregateColumn) {
      var firstRow = null;
      for (var h = 0; h < returned; h++) {
        if (ctx.rows[h] && typeof ctx.rows[h] === "object") { firstRow = ctx.rows[h]; break; }
      }
      var hoistCols = firstRow ? Object.keys(firstRow) : [];
      for (var hc = 0; hc < hoistCols.length; hc++) {
        var hoistName = hoistCols[hc];
        if (!isAggregateColumn(hoistName)) { continue; }
        var hoistValue = String(firstRow[hoistName]);
        var sameEverywhere = true;
        for (var hv = 0; hv < returned; hv++) {
          var hoistRow = ctx.rows[hv];
          if (!hoistRow || typeof hoistRow !== "object" || String(hoistRow[hoistName]) !== hoistValue) {
            sameEverywhere = false;
            break;
          }
        }
        if (sameEverywhere) {
          hoistedNames[hoistName] = true;
          hoisted.push(hoistName + " = " + hoistValue);
        }
      }
    }
    var bodyLines = [];
    for (var r = 0; r < rowCap; r++) {
      var row = ctx.rows[r];
      if (!row || typeof row !== "object") { continue; }
      var line = "";
      if (aggregateOnly) {
        var cols = Object.keys(row);
        var parts = [];
        for (var c = 0; c < cols.length; c++) {
          parts.push(cols[c] + " = " + String(row[cols[c]]));
        }
        line = parts.join(", ");
      } else {
        var plainRow = row;
        if (hoisted.length > 0) {
          plainRow = {};
          for (var pk in row) {
            if (!hoistedNames[pk]) { plainRow[pk] = row[pk]; }
          }
        }
        try { line = JSON.stringify(plainRow); } catch (e) { line = ""; }
        if (line && line.length > 500) {
          line = line.slice(0, 500) + "…";
        }
      }
      if (line) { bodyLines.push(line); }
    }
    if (bodyLines.length === 0) { return ""; }
    var shownNote = rowCap < returned ? ", showing the first " + rowCap : "";
    var headerLines = [label + questionClause];
    if (aggregateOnly) {
      headerLines.push("It returned the computed values below, over EVERY matching row in the whole table — exact totals, not a sample. They ARE the answer to that question: use them as given, and never recount from the example passages further down.");
    } else {
      if (hoisted.length > 0) {
        headerLines.push("Computed over the WHOLE table: " + hoisted.join(", ") + ". Those are the real totals for that question — never count the example rows instead.");
      }
      if (ctx.truncated === true) {
        headerLines.push((hoisted.length > 0 ? "It also returned " : "It returned ") + "a partial sample of " + returned + " matching rows" + shownNote + " — one page of a larger result, NOT a total.");
      } else if (hoisted.length > 0) {
        headerLines.push("It also returned " + returned + " matching rows" + shownNote + " as examples.");
      } else if (hasAggregateColumn) {
        headerLines.push("It returned all " + returned + " matching rows" + shownNote + " for that query.");
        headerLines.push("A column such as \"total_count\" is computed over the whole table, so its value is a real total; the number of rows is not.");
      } else {
        headerLines.push("It returned all " + returned + " matching rows" + shownNote + ", so " + returned + " is a real total for that question.");
      }
    }
    return headerLines.join("\n") + "\n" + bodyLines.join("\n");
  }
  var structuredSections = [];
  var productsDataSearchSection = readStructuredSection(withFinalPrices(params[31]), "Structured product data results");
  if (productsDataSearchSection) { structuredSections.push(productsDataSearchSection); }

  var semanticResults = [];
  if (semanticCtx && Array.isArray(semanticCtx.rows)) {
    semanticResults = semanticCtx.rows;
  } else if (semanticCtx && Array.isArray(semanticCtx.result)) {
    semanticResults = semanticCtx.result;
  } else if (semanticCtx && semanticCtx.result && Array.isArray(semanticCtx.result.rows)) {
    semanticResults = semanticCtx.result.rows;
  }

  var lexicalResults = [];
  if (lexicalCtx && Array.isArray(lexicalCtx.rows)) {
    lexicalResults = lexicalCtx.rows;
  } else if (lexicalCtx && Array.isArray(lexicalCtx.result)) {
    lexicalResults = lexicalCtx.result;
  } else if (lexicalCtx && lexicalCtx.result && Array.isArray(lexicalCtx.result.rows)) {
    lexicalResults = lexicalCtx.result.rows;
  }

  var seen = {};
  var merged = [];

  function addDoc(doc) {
    var key = doc.id || (doc.search_content || doc.content || "");
    if (key && !seen[key]) {
      seen[key] = true;
      merged.push(doc);
    }
  }

  semanticResults.forEach(function(doc) { addDoc(doc); });
  lexicalResults.forEach(function(doc) { addDoc(doc); });

  var passages = [];
  for (var i = 0; i < merged.length; i++) {
    var body = merged[i].content || merged[i].search_content || "";
    body = String(body).trim();
    if (body) { passages.push(body); }
  }
  var allPassages = structuredSections.concat(passages);
  var context = allPassages.join("\n\n---\n\n");

  return { context: context, hasContext: allPassages.length > 0, documentCount: passages.length };
}

function customHandler(previousContext, params) {
  const aiCtx = params[16];
  const msgsCtx = params[17];

  const fullResponse = aiCtx && aiCtx.fullResponse != null ? String(aiCtx.fullResponse) : "";

  let messages = [];
  if (msgsCtx && msgsCtx.value != null) {
    if (typeof msgsCtx.value === "string") {
      try { messages = JSON.parse(msgsCtx.value); } catch(e) { messages = []; }
    } else if (Array.isArray(msgsCtx.value)) {
      messages = msgsCtx.value;
    }
  }

  if (messages.length === 0) {
    return { streamMessages: messages };
  }

  const lastMsg = messages[messages.length - 1];
  if (lastMsg && (lastMsg.status === "pending" || lastMsg.status === "in_progress")) {
    const updated = messages.slice(0, -1).concat([{
      id: lastMsg.id,
      sender: lastMsg.sender,
      message: fullResponse,
      status: "in_progress"
    }]);
    return { streamMessages: updated };
  }

  return { streamMessages: messages };
}

function customHandler(previousContext, params) {
  const aiCtx = params[16];
  const msgsCtx = params[21];

  const response = aiCtx && aiCtx.response != null ? String(aiCtx.response)
    : (aiCtx && aiCtx.fullResponse != null ? String(aiCtx.fullResponse) : "");

  let messages = [];
  if (msgsCtx && msgsCtx.value != null) {
    if (typeof msgsCtx.value === "string") {
      try { messages = JSON.parse(msgsCtx.value); } catch(e) { messages = []; }
    } else if (Array.isArray(msgsCtx.value)) {
      messages = msgsCtx.value;
    }
  }

  const updated = messages.map(function(m) {
    if (m.status === "pending" || m.status === "in_progress") {
      return { id: m.id, sender: m.sender, message: response, status: "sent" };
    }
    return m;
  });

  return { finalMessages: updated };
}

function customHandler(previousContext, params) {
  var answerCtx = params[16];
  var mergeCtx = params[15];
  var UNKNOWN_MESSAGES = ["I apologize, but I don't have enough information in my knowledge base to answer your question."];

  var answer = "";
  if (answerCtx) {
    if (answerCtx.response != null) { answer = String(answerCtx.response); }
    else if (answerCtx.fullResponse != null) { answer = String(answerCtx.fullResponse); }
  }

  function normalize(value) {
    return String(value == null ? "" : value).replace(/\s+/g, " ").trim().toLowerCase();
  }

  var normalizedAnswer = normalize(answer);
  var matchedFallback = false;
  for (var i = 0; i < UNKNOWN_MESSAGES.length; i++) {
    var normalizedFallback = normalize(UNKNOWN_MESSAGES[i]);
    if (normalizedFallback.length === 0) { continue; }
    if (normalizedAnswer.indexOf(normalizedFallback) !== -1) { matchedFallback = true; break; }
  }
  var answeredFromKnowledge = normalizedAnswer.length > 0 && !matchedFallback;
  var hasContext = !!(mergeCtx && mergeCtx.hasContext);

  return { coveredByKnowledge: hasContext && answeredFromKnowledge };
}

